/* ============================================================
   FC NOVA — tiny WebAudio synth (no audio files)
   ============================================================ */
(function () {
  "use strict";

  const Sound = {
    ctx: null,
    master: null,
    noiseBuf: null,
    crowdSrc: null,
    crowdGain: null,
    enabled: true,

    init() {
      if (this.ctx) return;
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.7;
      this.master.connect(this.ctx.destination);

      const len = this.ctx.sampleRate * 3;
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.noiseBuf = buf;
    },

    resume() {
      this.init();
      if (!this.ctx) return;
      if (this.ctx.state === "suspended") this.ctx.resume();
    },

    setEnabled(v) {
      this.enabled = v;
      if (this.master) this.master.gain.setTargetAtTime(v ? 0.7 : 0, this.ctx.currentTime, 0.05);
    },

    tone(freq, dur, opts = {}) {
      if (!this.ctx || !this.enabled) return;
      const t = this.ctx.currentTime + (opts.delay || 0);
      const o = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      o.type = opts.type || "sine";
      o.frequency.setValueAtTime(freq, t);
      if (opts.to) o.frequency.exponentialRampToValueAtTime(Math.max(20, opts.to), t + dur);
      const vol = opts.vol == null ? 0.12 : opts.vol;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(vol, t + 0.012);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g).connect(this.master);
      o.start(t);
      o.stop(t + dur + 0.02);
    },

    noise(dur, opts = {}) {
      if (!this.ctx || !this.enabled) return;
      const t = this.ctx.currentTime + (opts.delay || 0);
      const s = this.ctx.createBufferSource();
      s.buffer = this.noiseBuf;
      s.loop = true;
      const f = this.ctx.createBiquadFilter();
      f.type = opts.filter || "bandpass";
      f.frequency.setValueAtTime(opts.freq || 900, t);
      if (opts.toFreq) f.frequency.exponentialRampToValueAtTime(opts.toFreq, t + dur);
      f.Q.value = opts.q == null ? 1 : opts.q;
      const g = this.ctx.createGain();
      const vol = opts.vol == null ? 0.1 : opts.vol;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(vol, t + (opts.attack || 0.01));
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      s.connect(f).connect(g).connect(this.master);
      s.start(t);
      s.stop(t + dur + 0.03);
    },

    click() {
      this.resize();
      this.tone(640, 0.05, { type: "triangle", vol: 0.06, to: 420 });
    },

    select() {
      this.resize();
      this.tone(520, 0.06, { type: "square", vol: 0.03 });
      this.tone(780, 0.08, { type: "square", vol: 0.03, delay: 0.045 });
    },

    kick() {
      this.resize();
      this.noise(0.09, { filter: "lowpass", freq: 900, toFreq: 180, vol: 0.3, q: 0.7 });
      this.tone(150, 0.11, { type: "sine", vol: 0.28, to: 55 });
    },

    pass() {
      this.resize();
      this.noise(0.05, { filter: "lowpass", freq: 1200, toFreq: 300, vol: 0.14 });
      this.tone(230, 0.06, { type: "sine", vol: 0.08, to: 140 });
    },

    tackle() {
      this.resize();
      this.noise(0.13, { filter: "lowpass", freq: 600, vol: 0.2 });
      this.tone(90, 0.12, { type: "square", vol: 0.07, to: 50 });
    },

    post() {
      this.resize();
      this.tone(1180, 0.35, { type: "triangle", vol: 0.16, to: 820 });
      this.tone(1720, 0.22, { type: "sine", vol: 0.08, to: 1300 });
    },

    save() {
      this.resize();
      this.noise(0.16, { filter: "lowpass", freq: 2000, vol: 0.16 });
      this.tone(300, 0.1, { type: "triangle", vol: 0.06, to: 180 });
    },

    whistle(long) {
      this.resize();
      const dur = long ? 0.7 : 0.32;
      this.tone(2350, dur, { type: "sine", vol: 0.09, to: 2260 });
      this.tone(2420, dur, { type: "sine", vol: 0.06, to: 2340 });
      if (long) this.tone(2380, 0.3, { type: "sine", vol: 0.08, delay: 0.42 });
    },

    goal() {
      this.resize();
      this.whistle(false);
      this.tone(392, 1.2, { type: "sawtooth", vol: 0.05, to: 396 });
      this.tone(523, 1.3, { type: "sawtooth", vol: 0.045, to: 528 });
      this.tone(659, 1.1, { type: "sawtooth", vol: 0.04, to: 665 });
      this.noise(2.4, { filter: "bandpass", freq: 900, toFreq: 1400, q: 0.5, vol: 0.22, attack: 0.25 });
      this.tone(880, 0.3, { type: "square", vol: 0.04, delay: 0.1 });
    },

    crowdOn() {
      this.init();
      if (!this.ctx || this.crowdSrc) return;
      const s = this.ctx.createBufferSource();
      s.buffer = this.noiseBuf;
      s.loop = true;
      const f = this.ctx.createBiquadFilter();
      f.type = "bandpass";
      f.frequency.value = 700;
      f.Q.value = 0.45;
      const g = this.ctx.createGain();
      g.gain.value = 0.018;
      s.connect(f).connect(g).connect(this.master);
      s.start();
      this.crowdSrc = s;
      this.crowdGain = g;
    },

    crowdOff() {
      if (!this.crowdSrc) return;
      try {
        this.crowdSrc.stop();
        this.crowdSrc.disconnect();
      } catch (e) { /* noop */ }
      this.crowdSrc = null;
      this.crowdGain = null;
    },

    pack() {
      this.resize();
      for (let i = 0; i < 4; i++) this.tone(300 + i * 120, 0.12, { type: "triangle", vol: 0.05, delay: i * 0.07 });
      this.noise(0.5, { filter: "highpass", freq: 1200, vol: 0.06, attack: 0.1 });
    },

    reveal(step) {
      this.resize();
      this.tone(440 + step * 120, 0.3, { type: "triangle", vol: 0.08, to: 660 + step * 120 });
      this.tone(660 + step * 160, 0.4, { type: "sine", vol: 0.04, delay: 0.03 });
    },

    win() {
      this.resize();
      [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.28, { type: "triangle", vol: 0.09, delay: i * 0.11 }));
    },

    lose() {
      this.resize();
      [392, 349, 311, 262].forEach((f, i) => this.tone(f, 0.26, { type: "triangle", vol: 0.07, delay: i * 0.12 }));
    },

    // called from pointer events; cheap guard
    resize() {
      if (!this.ctx) this.init();
      if (this.ctx && this.ctx.state === "suspended") this.ctx.resume();
    }
  };

  window.FCN = window.FCN || {};
  window.FCN.sound = Sound;
})();

/* ============================================================
   FC NOVA — save state, squad logic, packs, progression
   ============================================================ */
(function () {
  "use strict";
  const D = window.FCN.data;
  const KEY = "fcnova.save.v1";
  const clone = (o) => JSON.parse(JSON.stringify(o));

  const POS_FAMILY = {
    GK: "GK",
    CB: "DEF", LB: "DEF", RB: "DEF", LWB: "DEF", RWB: "DEF",
    CDM: "MID", CM: "MID", CAM: "MID", LM: "MID", RM: "MID",
    LW: "ATT", RW: "ATT", ST: "ATT"
  };
  const POS_RELATED = {
    CB: ["CDM"], LB: ["LWB", "LM"], RB: ["RWB", "RM"], LWB: ["LB", "LM"], RWB: ["RB", "RM"],
    CDM: ["CM", "CB"], CM: ["CDM", "CAM"], CAM: ["CM", "LM", "RM", "ST"],
    LM: ["LW", "LWB", "CM"], RM: ["RW", "RWB", "CM"],
    LW: ["LM", "ST", "CAM"], RW: ["RM", "ST", "CAM"], ST: ["LW", "RW", "CAM"]
  };

  function fitScore(playerPos, slotPos) {
    if (playerPos === slotPos) return 1;
    if ((playerPos === "GK") !== (slotPos === "GK")) return 0.35;
    if (POS_FAMILY[playerPos] === POS_FAMILY[slotPos]) return 0.9;
    if ((POS_RELATED[playerPos] || []).includes(slotPos)) return 0.82;
    return 0.64;
  }

  function autoPick(collection, formationKey) {
    const slots = D.FORMATIONS[formationKey].slots;
    const used = new Set();
    const result = new Array(slots.length).fill(null);
    const order = slots.map((s, i) => i).sort((a, b) => {
      const pa = slots[a].pos === "GK" ? 0 : 1;
      const pb = slots[b].pos === "GK" ? 0 : 1;
      if (pa !== pb) return pa - pb;
      return 0;
    });
    for (const idx of order) {
      const slot = slots[idx];
      let best = null;
      let bestScore = -1;
      for (const p of collection) {
        if (used.has(p.id)) continue;
        const score = p.ovr * 0.82 + fitScore(p.pos, slot.pos) * 22;
        if (score > bestScore) { bestScore = score; best = p; }
      }
      if (best) { result[idx] = best.id; used.add(best.id); }
    }
    // fill remaining slots with best unused
    const rest = collection.filter((p) => !used.has(p.id)).sort((a, b) => b.ovr - a.ovr);
    for (let i = 0; i < result.length; i++) {
      if (!result[i] && rest.length) result[i] = rest.shift().id;
    }
    return result;
  }

  function squadOverall(state) {
    const ids = state.squad.filter(Boolean);
    if (!ids.length) return 0;
    return Math.round(ids.reduce((sum, id) => {
      const p = state.collection.find((c) => c.id === id);
      return sum + (p ? p.ovr : 0);
    }, 0) / ids.length);
  }

  function squadBreakdown(state) {
    const slots = D.FORMATIONS[state.formation].slots;
    const groups = { atk: [], mid: [], def: [] };
    state.squad.forEach((id, i) => {
      const p = state.collection.find((c) => c.id === id);
      if (!p) return;
      const fam = POS_FAMILY[slots[i] ? slots[i].pos : p.pos];
      if (fam === "ATT") groups.atk.push(p.ovr);
      else if (fam === "MID") groups.mid.push(p.ovr);
      else if (fam === "DEF") groups.def.push(p.ovr);
      else groups.def.push(p.ovr * 0.6);
    });
    const avg = (a) => a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length) : 0;
    return { atk: avg(groups.atk), mid: avg(groups.mid), def: avg(groups.def) };
  }

  function defaultState() {
    const collection = D.STARTER_IDS.map((id) => clone(D.PLAYER_BY_ID[id])).filter(Boolean);
    const state = {
      v: 1,
      coins: 3200,
      gems: 60,
      xp: 0,
      trophies: 0,
      packsOpened: 0,
      bestWinGoals: 0,
      collection,
      formation: "4-3-3",
      squad: [],
      record: { w: 0, d: 0, l: 0, gf: 0, ga: 0 },
      settings: { sound: true },
      lastDaily: null,
      cup: null,
      createdAt: Date.now()
    };
    state.squad = autoPick(collection, state.formation);
    return state;
  }

  function load() {
    try {
      const raw = localStorage.getItem(KEY);
      if (!raw) return defaultState();
      const parsed = JSON.parse(raw);
      if (!parsed || !Array.isArray(parsed.collection)) return defaultState();
      const base = defaultState();
      const s = Object.assign(base, parsed);
      s.settings = Object.assign({ sound: true }, parsed.settings || {});
      s.record = Object.assign({ w: 0, d: 0, l: 0, gf: 0, ga: 0 }, parsed.record || {});
      if (!D.FORMATIONS[s.formation]) s.formation = "4-3-3";
      // repair squad
      const ids = new Set(s.collection.map((p) => p.id));
      if (!Array.isArray(s.squad) || s.squad.length !== 11) s.squad = autoPick(s.collection, s.formation);
      s.squad = s.squad.map((id) => (ids.has(id) ? id : null));
      if (s.squad.filter(Boolean).length < 11) s.squad = autoPick(s.collection, s.formation);
      return s;
    } catch (e) {
      console.warn("save load failed", e);
      return defaultState();
    }
  }

  let state = load();
  const listeners = new Set();

  function save() {
    try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) { /* private mode */ }
  }
  function changed() {
    save();
    listeners.forEach((fn) => { try { fn(state); } catch (e) { console.error(e); } });
  }
  function onChange(fn) { listeners.add(fn); return () => listeners.delete(fn); }
  function getState() { return state; }

  function getPlayer(id) { return state.collection.find((p) => p.id === id) || null; }
  function getSquadPlayers() {
    const slots = D.FORMATIONS[state.formation].slots;
    return slots.map((slot, i) => ({ slot, player: getPlayer(state.squad[i]) }));
  }
  function benchPlayers() {
    const inSquad = new Set(state.squad);
    return state.collection.filter((p) => !inSquad.has(p.id)).sort((a, b) => b.ovr - a.ovr);
  }

  function setFormation(key) {
    if (!D.FORMATIONS[key]) return;
    state.formation = key;
    state.squad = autoPick(state.collection, key);
    changed();
  }

  function autoSquad() {
    state.squad = autoPick(state.collection, state.formation);
    changed();
  }

  function setSlot(index, playerId) {
    if (index < 0 || index > 10) return;
    if (!getPlayer(playerId)) return;
    const existing = state.squad.indexOf(playerId);
    if (existing === index) return;
    if (existing >= 0) {
      const tmp = state.squad[index];
      state.squad[index] = playerId;
      state.squad[existing] = tmp;
    } else {
      state.squad[index] = playerId;
    }
    changed();
  }

  function addCoins(n) { state.coins = Math.max(0, state.coins + n); changed(); }
  function addGems(n) { state.gems = Math.max(0, state.gems + n); changed(); }

  function canAfford(pack) { return state.coins >= pack.price; }

  function openPack(pack) {
    if (state.coins < pack.price) return { ok: false, reason: "coins" };
    state.coins -= pack.price;
    const owned = new Set(state.collection.map((p) => p.id));
    const cards = [];
    for (let i = 0; i < pack.count; i++) {
      let candidates = D.PLAYER_POOL.filter((p) => p.ovr >= pack.min && p.ovr <= pack.max && !owned.has(p.id));
      let player;
      if (candidates.length) {
        // prefer the higher end a little
        candidates.sort((a, b) => b.ovr - a.ovr);
        const pool = candidates.slice(0, Math.max(1, Math.ceil(candidates.length * 0.7)));
        player = clone(pool[Math.floor(Math.random() * pool.length)]);
      } else {
        player = D.generatePlayer(pack.min + Math.random() * (pack.max - pack.min), null);
        player.club = "NOVA FC";
      }
      // widen a touch: small chance of a surprise elite
      if (Math.random() < 0.04 + (pack.id === "elite" ? 0.25 : 0)) {
        const boost = D.generatePlayer(Math.min(90, pack.max + 4), player.pos);
        boost.name = player.name;
        player = boost;
      }
      owned.add(player.id);
      state.collection.push(player);
      cards.push(player);
    }
    state.packsOpened = (state.packsOpened || 0) + 1;
    changed();
    return { ok: true, cards };
  }

  function dailyClaim() {
    const today = new Date().toISOString().slice(0, 10);
    if (state.lastDaily === today) return { ok: false };
    state.lastDaily = today;
    state.coins += 750;
    changed();
    return { ok: true, amount: 750 };
  }
  function dailyAvailable() {
    return state.lastDaily !== new Date().toISOString().slice(0, 10);
  }

  function recordMatch({ goalsFor, goalsAgainst, won, drawn, extraTrophies }) {
    state.record.gf += goalsFor;
    state.record.ga += goalsAgainst;
    if (won) state.record.w++;
    else if (drawn) state.record.d++;
    else state.record.l++;
    if (won) state.bestWinGoals = Math.max(state.bestWinGoals || 0, goalsFor - goalsAgainst);
    const coins = won ? 900 + goalsFor * 80 : drawn ? 450 + goalsFor * 50 : 200 + goalsFor * 30;
    const xp = won ? 200 + goalsFor * 12 : drawn ? 110 + goalsFor * 8 : 55 + goalsFor * 6;
    state.coins += coins;
    state.xp += xp;
    if (extraTrophies) state.trophies += extraTrophies;
    changed();
    return { coins, xp };
  }

  function levelInfo() {
    const level = Math.floor(state.xp / 1000) + 1;
    const into = state.xp % 1000;
    const ranks = ["Tân binh", "HLV tập sự", "HLV chuyên nghiệp", "Chiến lược gia", "Bậc thầy chiến thuật", "Huyền thoại"];
    return { level, into, need: 1000, rank: ranks[Math.min(ranks.length - 1, Math.floor((level - 1) / 2))] };
  }

  function achievements() {
    const r = state.record;
    const wins = r.w;
    const best = state.collection.reduce((a, p) => Math.max(a, p.ovr), 0);
    const ovr = squadOverall(state);
    return [
      { id: "first", icon: "ball", title: "Trận đầu ra sân", desc: "Hoàn thành trận đấu đầu tiên", done: r.w + r.d + r.l >= 1 },
      { id: "win5", icon: "trophy", title: "Chuỗi ngày chiến thắng", desc: "Thắng 5 trận", done: wins >= 5 },
      { id: "goals25", icon: "bolt", title: "Cơn lốc tấn công", desc: "Ghi 25 bàn thắng", done: r.gf >= 25 },
      { id: "elite", icon: "shield", title: "Ngôi sao tinh anh", desc: "Sở hữu cầu thủ 85+ OVR", done: best >= 85 },
      { id: "ovr80", icon: "squad", title: "Đội hình trong mơ", desc: "Đạt độ mạnh đội hình 80", done: ovr >= 80 },
      { id: "cup", icon: "trophy", title: "Nhà vô địch", desc: "Vô địch Cúp Nova", done: state.trophies >= 1 },
      { id: "packs10", icon: "store", title: "Tay chơi chuyển nhượng", desc: "Mở 10 gói cầu thủ", done: (state.packsOpened || 0) >= 10 },
      { id: "bigwin", icon: "ball", title: "Đại thắng", desc: "Thắng với cách biệt 3 bàn", done: (state.bestWinGoals || 0) >= 3 }
    ];
  }

  function reset() {
    state = defaultState();
    changed();
    return state;
  }

  window.FCN.store = {
    getState, getPlayer, getSquadPlayers, benchPlayers, squadOverall, squadBreakdown,
    setFormation, autoSquad, setSlot, autoPick, openPack, canAfford, addCoins, addGems,
    dailyClaim, dailyAvailable, recordMatch, levelInfo, achievements, reset, save, changed, onChange,
    fitScore, POS_FAMILY
  };
})();

/* ============================================================
   FC NOVA — interface rendering & interactions
   ============================================================ */
(function () {
  "use strict";
  const D = window.FCN.data;
  const S = window.FCN.store;
  const Sound = window.FCN.sound;
  const $ = (sel, root) => (root || document).querySelector(sel);
  const $$ = (sel, root) => Array.from((root || document).querySelectorAll(sel));
  const fmt = (n) => Math.round(n).toLocaleString("vi-VN");

  const resultHandler = { fn: null };
  let currentScreen = "home";
  let setupCtx = null;

  /* ---------------- tiny helpers ---------------- */
  function esc(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  }
  function rarityLabel(p) { return D.RARITY_LABEL[p.rarity] || "Đồng"; }
  function nationName(code) { return D.NATIONS[code] || code; }

  function avatarSVG(p) {
    const uid = String(p.id).replace(/[^a-zA-Z0-9]/g, "");
    const elite = p.rarity === "elite" || p.rarity === "legend";
    const kitA = elite ? "#f2fbff" : "#172231";
    const kitB = elite ? "#b9d6e8" : "#0a111c";
    const trim = elite ? "#b072ff" : "#c8ff2e";
    const numColor = elite ? "#1b0a33" : "#eaf7ff";
    const skin = p.skin || "#e0ad7f";
    const skinDark = shade(skin, -0.16);
    const hair = p.hair || "#1b1b1b";
    const style = p.hairStyle || 0;
    let hairPath = "";
    if (style === 0) {
      hairPath = `<path d="M33 54 Q34 36 50 35 Q66 36 67 54 Q63 44 50 44 Q37 44 33 54Z" fill="${hair}"/><path d="M36 43 Q43 38 50 38" stroke="rgba(255,255,255,.22)" stroke-width="1.5" fill="none"/>`;
    } else if (style === 1) {
      hairPath = `<path d="M33 56 Q33 39 50 38 Q67 39 67 56 L64 49 Q58 45 50 45 Q42 45 36 49Z" fill="${hair}"/><path d="M38 47 Q44 42 51 42" stroke="rgba(255,255,255,.18)" stroke-width="1.5" fill="none"/>`;
    } else if (style === 2) {
      hairPath = `<g fill="${hair}"><circle cx="36" cy="44" r="6"/><circle cx="42" cy="39" r="6.4"/><circle cx="50" cy="37" r="6.5"/><circle cx="58" cy="39" r="6.4"/><circle cx="64" cy="44" r="6"/><path d="M33 55 Q33 38 50 37 Q67 38 67 55 Q62 46 50 46 Q38 46 33 55Z"/></g>`;
    } else {
      hairPath = `<path d="M33 55 Q33 36 50 35 Q67 36 67 55 L67 68 Q63 70 62 60 L62 47 Q56 43 50 43 Q44 43 38 47 L38 60 Q37 70 33 68Z" fill="${hair}"/>`;
    }
    return `<svg viewBox="0 0 100 132" aria-hidden="true">
      <defs>
        <linearGradient id="k${uid}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${kitA}"/><stop offset="1" stop-color="${kitB}"/></linearGradient>
        <radialGradient id="f${uid}" cx="42%" cy="36%" r="70%"><stop offset="0" stop-color="${shade(skin, 0.14)}"/><stop offset=".7" stop-color="${skin}"/><stop offset="1" stop-color="${skinDark}"/></radialGradient>
      </defs>
      <ellipse cx="50" cy="127" rx="32" ry="6" fill="#000" opacity=".2"/>
      <path d="M23 132 C23 108 30 94 40 89 L60 89 C70 94 77 108 77 132 Z" fill="url(#k${uid})"/>
      <path d="M23 132 C15 125 12 112 15 101 L27 92 L33 105 L28 115 L30 132 Z" fill="url(#k${uid})"/>
      <path d="M77 132 C85 125 88 112 85 101 L73 92 L67 105 L72 115 L70 132 Z" fill="url(#k${uid})"/>
      <path d="M27 92 L33 105 M73 92 L67 105" stroke="${trim}" stroke-width="2.2" opacity=".9"/>
      <path d="M41 89 L50 100 L59 89" fill="none" stroke="${trim}" stroke-width="2.6"/>
      <text x="50" y="124" font-family="Barlow Condensed, sans-serif" font-weight="800" font-size="23" fill="${numColor}" text-anchor="middle" opacity=".92">${p.number || 9}</text>
      <path d="M44 76 L44 91 Q50 97 56 91 L56 76 Z" fill="${skinDark}"/>
      <ellipse cx="33" cy="61" rx="3" ry="4.4" fill="${skinDark}"/>
      <ellipse cx="67" cy="61" rx="3" ry="4.4" fill="${skinDark}"/>
      <ellipse cx="50" cy="59" rx="16.2" ry="18.6" fill="url(#f${uid})"/>
      <path d="M36 69 Q42 79 50 79 Q58 79 64 69 Q58 76 50 76 Q42 76 36 69Z" fill="${skinDark}" opacity=".5"/>
      ${hairPath}
      <path d="M37 53 Q40 49 43 51" stroke="${shade(hair, 0.15)}" stroke-width="1.4" fill="none" opacity=".8" stroke-linecap="round"/>
    </svg>`;
  }
  function shade(hex, amt) {
    let h = hex.replace("#", "");
    if (h.length === 3) h = h.split("").map((c) => c + c).join("");
    const num = parseInt(h, 16);
    let r = (num >> 16) & 255, g = (num >> 8) & 255, b = num & 255;
    if (amt >= 0) { r = r + (255 - r) * amt; g = g + (255 - g) * amt; b = b + (255 - b) * amt; }
    else { r = r * (1 + amt); g = g * (1 + amt); b = b * (1 + amt); }
    return "#" + [r, g, b].map((v) => Math.round(v).toString(16).padStart(2, "0")).join("");
  }

  function playerCard(p, opts = {}) {
    if (!p) return "";
    return `<div class="pcard r-${p.rarity} ${opts.className || ""}" data-player-card="${p.id}">
      <div class="pcard-inner">
        <div class="pcard-shine"></div>
        <div class="pcard-head"><b>${p.ovr}</b><span>${p.pos}</span></div>
        <div class="pcard-badge">${p.nation}</div>
        <div class="pcard-num">${String(p.number || 9).padStart(2, "0")}</div>
        <div class="pcard-art">${avatarSVG(p)}</div>
        <div class="pcard-foot"><b>${esc(p.name)}</b><span>${p.nation} · ${esc(p.club || "NOVA FC")}</span></div>
      </div>
    </div>`;
  }

  /* ---------------- render ---------------- */
  function render() {
    const st = S.getState();
    renderResources(st);
    renderHome(st);
    renderSquad(st);
    renderStore(st);
    renderProfile(st);
    renderDaily(st);
    renderSound(st);
  }

  function renderResources(st) {
    $("#res-coins").textContent = fmt(st.coins);
    $("#res-gems").textContent = fmt(st.gems);
