        }).join("")}</div>
        <div class="modal-actions"><button class="btn btn-ghost" data-close>ĐỂ SAU</button><button class="btn btn-primary" id="cup-start"><svg class="ico"><use href="#i-play"/></svg> BẮT ĐẦU CÚP</button></div>
      `);
