          Sound.whistle(false);
        }
      } else if (this.state === "restart") {
        this.restartTimer -= dt;
        this.updateRestartMovement(dt);
        if (this.restartTimer <= 0) this.finishRestart();
      } else if (this.state === "halftime") {
        this.stateTimer -= dt;
